import logging

from taf.fdsw.rc.schemas.FDSW19A.autoconnection_parameters_builder_19a import \
    Validator
from taf.fdsw.rc.schemas.FDSW21A.autoconnection_parameters_builder_21a import \
    AutoconnectionParametersBuilder21A

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoconnectionParametersBuilder21D(AutoconnectionParametersBuilder21A):
    def __init__(self, **kwargs):
        super(AutoconnectionParametersBuilder21D, self).__init__(**kwargs)
        self.dns_parameters = self._get_dns_parameters(**kwargs)

        if 'ethernet_port' in kwargs:
            ethernet_port = '' if kwargs['ethernet_port'] == "AUTO" else kwargs['ethernet_port']
            # TODO remove this once API is fixed on RC side
            self.management_plane_parameters.update(selectedEthPort=ethernet_port)

    def _get_dns_parameters(self, **kwargs):
        dns_parameters = {}
        if 'primary_dns' in kwargs:
            primary_dns = kwargs['primary_dns']

            dns_parameters.update(primaryDNS=Validator.validate_param(
                'primary_dns',
                primary_dns,
                (primary_dns is None or Validator.validate_ip_address(
                    primary_dns))))

        if 'secondary_dns' in kwargs:
            secondary_dns = kwargs['secondary_dns']

            dns_parameters.update(secondaryDNS=Validator.validate_param(
                'secondary_dns',
                secondary_dns,
                (secondary_dns is None or Validator.validate_ip_address(
                    secondary_dns))))
        return dns_parameters

    def as_dict(self):
        attributes = super(AutoconnectionParametersBuilder21D, self).as_dict()
        if self.dns_parameters:
            attributes.update(dnsParameters=self.dns_parameters)
        return attributes
